package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen2Test {

    @Test
    public void testIsNumber_NullAndEmpty() {
        assertFalse("Null should return false", NumberUtils.isNumber(null));
        assertFalse("Empty string should return false", NumberUtils.isNumber(""));
    }

    @Test
    public void testIsNumber_Integers() {
        assertTrue("Simple integer", NumberUtils.isNumber("123"));
        assertTrue("Negative integer", NumberUtils.isNumber("-123"));
        assertTrue("Zero", NumberUtils.isNumber("0"));
        assertTrue("Large integer", NumberUtils.isNumber("999999999"));
    }

    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue("Hexadecimal", NumberUtils.isNumber("0x1A"));
        assertTrue("Hexadecimal lowercase", NumberUtils.isNumber("0xaf"));
        assertTrue("Hexadecimal with sign", NumberUtils.isNumber("-0x12"));
        assertFalse("Incomplete hex", NumberUtils.isNumber("0x"));
        assertFalse("Invalid hex char", NumberUtils.isNumber("0xG"));
        assertFalse("Hex with decimal", NumberUtils.isNumber("0x1.2"));
    }

    @Test
    public void testIsNumber_Decimals() {
        assertTrue("Decimal point", NumberUtils.isNumber("123.45"));
        assertTrue("Trailing decimal point", NumberUtils.isNumber("123."));
        assertTrue("Decimal with sign", NumberUtils.isNumber("-123.45"));
        assertFalse("Multiple decimal points", NumberUtils.isNumber("123.45.67"));
        assertFalse("Decimal in exponent", NumberUtils.isNumber("1e2.5"));
        assertFalse("Only decimal point", NumberUtils.isNumber("."));
        assertFalse("Decimal without leading digit", NumberUtils.isNumber(".e5"));
    }

    @Test
    public void testIsNumber_Exponents() {
        assertTrue("Scientific notation", NumberUtils.isNumber("1e10"));
        assertTrue("Scientific notation upper", NumberUtils.isNumber("1E10"));
        assertTrue("Scientific notation negative exponent", NumberUtils.isNumber("1e-10"));
        assertTrue("Scientific notation positive exponent", NumberUtils.isNumber("1e+10"));
        assertTrue("Decimal with exponent", NumberUtils.isNumber("1.2e10"));
        assertFalse("Exponent without digit", NumberUtils.isNumber("e10"));
        assertFalse("Multiple exponents", NumberUtils.isNumber("1e2e3"));
        assertFalse("Trailing exponent sign", NumberUtils.isNumber("1e+"));
        assertFalse("Trailing exponent", NumberUtils.isNumber("1e"));
        assertFalse("Exponent with decimal point", NumberUtils.isNumber("1e2.5"));
    }

    @Test
    public void testIsNumber_TypeQualifiers() {
        // d, D, f, F
        assertTrue("Float qualifier f", NumberUtils.isNumber("123f"));
        assertTrue("Float qualifier F", NumberUtils.isNumber("123F"));
        assertTrue("Double qualifier d", NumberUtils.isNumber("123d"));
        assertTrue("Double qualifier D", NumberUtils.isNumber("123D"));
        assertTrue("Float qualifier with exponent", NumberUtils.isNumber("1e2f"));

        // l, L
        assertTrue("Long qualifier l", NumberUtils.isNumber("123l"));
        assertTrue("Long qualifier L", NumberUtils.isNumber("123L"));
        assertFalse("Long qualifier with exponent", NumberUtils.isNumber("1e2l"));
        assertFalse("Long qualifier with exponent L", NumberUtils.isNumber("1e2L"));
    }

    @Test
    public void testIsNumber_EdgeCases() {
        assertFalse("Just a sign", NumberUtils.isNumber("-"));
        assertFalse("Just a plus sign", NumberUtils.isNumber("+"));
        assertFalse("Sign and dot", NumberUtils.isNumber("-."));
        assertFalse("Sign and E", NumberUtils.isNumber("-E"));
        assertFalse("Sign and E and sign", NumberUtils.isNumber("-E+"));
        assertFalse("Invalid characters", NumberUtils.isNumber("12a3"));
        assertFalse("Space in middle", NumberUtils.isNumber("12 3"));
        assertFalse("Leading space", NumberUtils.isNumber(" 123"));
        assertFalse("Trailing space", NumberUtils.isNumber("123 "));
    }

    @Test
    public void testIsNumber_ComplexCombinations() {
        assertTrue("Complex valid", NumberUtils.isNumber("-1.23E-4f"));
        assertTrue("Complex valid long", NumberUtils.isNumber("123L"));
        assertFalse("Complex invalid", NumberUtils.isNumber("1.2.3e4"));
        assertFalse("Invalid sign placement", NumberUtils.isNumber("12-3"));
    }
}
